#!/usr/bin/env dotnet
#:include *.cs
#:include Models/*.cs
#:exclude Scratch.cs

var person = new Person("Ada", "Lovelace");
Console.WriteLine(Formatter.UpperFullName(person));

static class Formatter
{
    public static string UpperFullName(Person p) =>
        $"{p.FirstName} {p.LastName}".ToUpperInvariant();
}

